//! 🧪️ Public production Actor checkout and receiving laws retain actual results on every refusal.
use semio_framework_actor::*;
use semio_framework_value::RetainedCloneProgress;
#[global_allocator]
static HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
fn law()->serde_json::Value{serde_json::from_str(include_str!("../../🧫️fixtures/🔣️.json")).unwrap()}
fn original()->RetainedTurnInput{let policy:serde_json::Value=serde_json::from_str(include_str!("../../../📃️policy/🧫️fixtures/🔣️.json")).unwrap();serde_json::from_value(policy["input"].clone()).unwrap()}
fn result(input:RetainedTurnInput,spent:RetainedCloneProgress)->TurnResult{TurnResult{retained_receipt:input.return_original(spent).unwrap(),ui_patches:Vec::new(),effects:vec![81],command_ingress:Vec::new(),cold_pair_ingress:Default::default(),lifecycle_receipt:None,ui_patch_receipt:None,next_wake:None,status:TurnStatus::Idle,usage:Usage{fuel:100,wall_us:50,memory_bytes:1024}}}
async fn actor(kernel:&mut Kernel,input:RetainedTurnInput)->ActorId{let package=PackageId("original-public-receiving".into());kernel.activate(package.clone(),7,ActorKind::PluginApp{plugin:package,app_id:"original".into(),instance_id:0},Lane::Interactive,None,ActivationEvent::Manual,input).await}
async fn submit(kernel:&mut Kernel,actor:ActorId,seq:u64){let original=Envelope{to:actor,from:Origin::Kernel,lane:Lane::Interactive,seq,deadline_ms:None,coalesce:None,cancel_of:None,payload:Payload::Event{bytes:vec![1]}};assert_ne!(kernel.submit(&original).await,Backpressure::Rejected)}
async fn snapshot(kernel:&Kernel,actor:ActorId)->(serde_json::Value,ActorStatus){let record=kernel.actor_record(actor).await.unwrap();(serde_json::to_value(record.metrics).unwrap(),record.status)}
#[semio_framework_async_macros::async_test]
async fn original_public_actor_unissued_return_preserves_result_and_metrics_without_heap(){let law=law();let input=original();let mut kernel=Kernel::new(ShardKind::Native,2,0,1).await;let actor=actor(&mut kernel,input).await;let output=result(input,Default::default());let pointer=output.effects.as_ptr();let before=snapshot(&kernel,actor).await;let(refused,heap)=observe(||semio_framework_async::poll::resolve_ready(kernel.complete(actor,&output,1)));assert_eq!(heap,(0,0));assert_eq!(refused.unwrap_err().to_string(),law["unissuedRefusal"].as_str().unwrap());assert_eq!(snapshot(&kernel,actor).await,before);assert_eq!(output.effects.as_ptr(),pointer);eprintln!("[DEBUG] actual public Actor unissued original result pointer={pointer:p} borrowed metrics/status unchanged refusal heap0");}
#[semio_framework_async_macros::async_test]
async fn original_public_actor_issued_receipts_reject_all_forged_axes_and_duplicate_without_renewal(){let law=law();let input=original();let mut kernel=Kernel::new(ShardKind::Native,2,0,1).await;let actor=actor(&mut kernel,input).await;submit(&mut kernel,actor,1).await;let first=kernel.tick(1).await.run.pop().unwrap();assert_eq!(first.budget.retained,input);submit(&mut kernel,actor,2).await;assert!(kernel.tick(2).await.run.is_empty());assert_eq!(kernel.mailbox_len(actor),Some(1));let spent=serde_json::from_value(law["spent"][0].clone()).unwrap();let output=result(first.budget.retained,spent);let original_pointer=output.effects.as_ptr();let before=snapshot(&kernel,actor).await;for axis in 0..13{let mut forged=output.clone();match axis{0=>forged.retained_receipt.input.operation+=1,1=>forged.retained_receipt.input.generation+=1,2=>forged.retained_receipt.input.epoch+=1,3=>forged.retained_receipt.input.grant.maximum_items+=1,4=>forged.retained_receipt.input.grant.maximum_copy_bytes+=1,5=>forged.retained_receipt.input.grant.maximum_capacity_bytes+=1,6=>forged.retained_receipt.input.grant.maximum_release_bytes+=1,7=>forged.retained_receipt.input.grant.maximum_depth+=1,8=>forged.retained_receipt.remaining.maximum_items+=1,9=>forged.retained_receipt.remaining.maximum_copy_bytes+=1,10=>forged.retained_receipt.remaining.maximum_capacity_bytes+=1,11=>forged.retained_receipt.remaining.maximum_release_bytes+=1,_=>forged.retained_receipt.remaining.maximum_depth+=1}let pointer=forged.effects.as_ptr();let(refused,heap)=observe(||semio_framework_async::poll::resolve_ready(kernel.complete(actor,&forged,3)));assert_eq!(heap,(0,0));assert_eq!(refused.unwrap_err().to_string(),law["receiptRefusal"].as_str().unwrap());assert_eq!(forged.effects.as_ptr(),pointer);assert_eq!(snapshot(&kernel,actor).await,before)}kernel.complete(actor,&output,4).await.unwrap();assert_eq!(output.effects.as_ptr(),original_pointer);let before=snapshot(&kernel,actor).await;let(refused,heap)=observe(||semio_framework_async::poll::resolve_ready(kernel.complete(actor,&output,5)));assert!(refused.is_err());assert_eq!(heap,(0,0));assert_eq!(snapshot(&kernel,actor).await,before);let second=kernel.tick(6).await.run.pop().unwrap();assert_eq!(second.budget.retained.operation,input.operation);assert_eq!(second.budget.retained.generation,input.generation);assert_eq!(second.budget.retained.epoch,law["epochs"][1].as_u64().unwrap());assert_eq!(serde_json::to_value(second.budget.retained.grant).unwrap(),law["remaining"][0]);assert!(kernel.complete(actor,&output,7).await.is_err());let spent=serde_json::from_value(law["spent"][1].clone()).unwrap();let output=result(second.budget.retained,spent);kernel.complete(actor,&output,8).await.unwrap();submit(&mut kernel,actor,3).await;assert!(kernel.tick(9).await.run.is_empty());assert_eq!(kernel.mailbox_len(actor),Some(1));assert_eq!(kernel.retained_turn(actor).unwrap().grant,output.retained_receipt.remaining);eprintln!("[DEBUG] actual public Actor original71/3 epochs19/20 all13 forged axes heap0 duplicate rejected same result pointer={original_pointer:p} remaining conserved all4 depth64 exhausted mailbox retained no renewal");}
#[semio_framework_async_macros::async_test]
async fn original_public_actor_zero_spend_and_epoch_overflow_preserve_original_mailbox(){let law=law();for overflow in [false,true]{let mut input=original();if overflow{input.epoch=law["overflow"]["epoch"].as_str().unwrap().parse().unwrap()}let mut kernel=Kernel::new(ShardKind::Native,2,0,1).await;let actor=actor(&mut kernel,input).await;assert!(kernel.tick(0).await.run.is_empty());assert_eq!(kernel.retained_turn(actor).unwrap(),input);submit(&mut kernel,actor,1).await;let first=kernel.tick(1).await.run.pop().unwrap();assert_eq!(first.budget.retained,input);let output=result(input,Default::default());kernel.complete(actor,&output,2).await.unwrap();submit(&mut kernel,actor,2).await;if overflow{assert!(kernel.tick(3).await.run.is_empty());assert_eq!(kernel.mailbox_len(actor),Some(1));assert_eq!(kernel.retained_turn(actor).unwrap(),input)}else{let second=kernel.tick(3).await.run.pop().unwrap();assert_eq!(second.budget.retained.epoch,law["zeroSpend"]["secondEpoch"].as_u64().unwrap());assert_eq!(second.budget.retained.grant,input.grant);assert!(kernel.complete(actor,&output,4).await.is_err());let output=result(second.budget.retained,Default::default());kernel.complete(actor,&output,5).await.unwrap();}}eprintln!("[DEBUG] actual public Actor empty admission epoch unchanged, zero-spend exact19-to20 same grant stale receipt refused, original maximumu64 epoch refuses next checkout before mailbox drain");}

#[semio_framework_async_macros::async_test]
async fn original_public_actor_turn_pack_preserves_independent_input_and_full_grant_without_heap(){
 let policy:serde_json::Value=serde_json::from_str(include_str!("../../../📃️policy/🧫️fixtures/🔣️.json")).unwrap();let input=original();
 for lane in [Lane::Interactive,Lane::UserVisible,Lane::Background,Lane::Maintenance]{
  let budget=lane_defaults::budget_for(lane,input);let scaled=budget.scaled(0.25).await;let mut kernel=Kernel::new(ShardKind::Native,2,0,1).await;let package=PackageId("original-public-wire".into());let actor=kernel.activate(package.clone(),7,ActorKind::PluginApp{plugin:package,app_id:"original".into(),instance_id:0},lane,None,ActivationEvent::Manual,input).await;submit(&mut kernel,actor,1).await;let issued=kernel.tick(1).await.run.pop().unwrap();assert_eq!(issued.budget.retained,input);let turn=TurnGrant{budget:scaled,envelopes:Vec::new(),..issued};let mut bytes=Vec::with_capacity(256);let backing=bytes.as_ptr();let(encoded,heap)=observe(||semio_framework_async::poll::resolve_ready(turn.pack_encode(&mut bytes)));encoded.unwrap();assert_eq!(heap,(0,0));assert_eq!(bytes.as_ptr(),backing);assert_eq!(bytes.len(),policy["wire"]["emptyTurnGrantBytes"].as_u64().unwrap()as usize);let mut offset=0;let(decoded,heap)=observe(||semio_framework_async::poll::resolve_ready(TurnGrant::pack_decode(&bytes,&mut offset)));assert_eq!(heap,(0,0));assert_eq!(decoded.unwrap(),turn);assert_eq!(offset,bytes.len());assert_eq!(turn.budget.retained,input);
 }
 eprintln!("[DEBUG] actual public Actor four lanes independent original71/3/19 full5 grant survives scheduling scale and109-byte original TurnGrant wire one64-byte retained input plus34-byte scheduling ceilings encode/decode heap0");
}

